use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::fs;
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-fixed-odd-screen176";
fn read(n:&str)->Value{serde_json::from_slice(&fs::read(format!("{R}/{n}")).unwrap()).unwrap()}fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn n(v:&Value,k:&str)->u64{v[k].as_u64().unwrap()}
fn main(){assert!(!std::path::Path::new(&format!("{R}/review.json")).exists());let pins=read("pins.json");for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let plan=read("plan.json");for s in plan["steps"].as_array().unwrap(){let root=format!("{R}/runs/{}",s["name"].as_str().unwrap());let exit:Value=serde_json::from_slice(&fs::read(format!("{root}/exit.json")).unwrap()).unwrap();assert_eq!(exit["success"],true);assert_eq!(exit["returncode"],0);for stream in["stdout","stderr"]{assert_eq!(hash(&format!("{root}/{stream}.log")),exit[format!("{stream}_sha256")].as_str().unwrap());}let cmd:Value=serde_json::from_slice(&fs::read(format!("{root}/command.json")).unwrap()).unwrap();assert!(cmd["argv"].as_array().unwrap().ends_with(s["argv"].as_array().unwrap()));assert_eq!(cmd["environment"],json!({}));}assert_eq!(read("runs/result.json")["status"],"complete");assert_eq!(read("runs/attempt-0.json")["resume"],false);assert_eq!(fs::read_dir(format!("{R}/runs")).unwrap().filter(|e|e.as_ref().unwrap().file_name().to_string_lossy().starts_with("attempt-")).count(),1);
let a=read("analysis.json");let c=&a["candidate"];let mut totals=[0u64;5];for(i,row)in c["rows"].as_array().unwrap().iter().enumerate(){assert_eq!(n(row,"position"),i as u64);totals[0]+=n(row,"arrivals");totals[1]+=row["occupied_per_part"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()).sum::<u64>();totals[2]+=n(row,"overlap_slots");let slot=n(row,"last_used_slot_plus1");assert!(slot<=2048);let fold=2*slot.saturating_sub(1);assert_eq!(n(row,"dense_weighted_fold_model_adds"),fold);totals[3]+=fold;let doubling=u64::from(slot>1);assert_eq!(n(row,"odd_weight_doublings"),doubling);totals[4]+=doubling;}for(i,k)in["arrivals","first_assignments","part_merges","dense_weighted_fold_model_adds","odd_weight_doublings_separate"].iter().enumerate(){assert_eq!(totals[i],n(c,k));}let skew=c["skew_corrections_by_part_component"].as_array().unwrap().iter().flat_map(|v|v.as_array().unwrap()).map(|v|v.as_u64().unwrap()).sum::<u64>();assert_eq!(skew,n(c,"skew_correction_leaves"));assert_eq!(skew.saturating_sub(1),n(c,"correction_tree_joins"));assert_eq!(u64::from(skew>0),n(c,"final_correction_combinations"));let main=totals[0]-totals[1]+totals[2]+totals[3];assert_eq!(main,n(c,"main_generic_addition_model_total"));let complete=main+skew;assert_eq!(complete,n(c,"complete_generic_addition_model_total"));let baseline=read("baseline.json");assert_eq!(baseline,a["frozen_full_radix_model"]);assert_eq!(n(&baseline,"generic_addition_model_total"),634405);let selected=complete<n(&baseline,"generic_addition_model_total");assert_eq!(a["generic_addition_model_selects_native"],selected);assert_eq!(n(&a,"actual_components_checked"),60178);assert_eq!(n(&a,"extra_exhaustive_boundary_cases"),8569);assert_eq!(n(&a,"extra_random_cases"),20000);
// Check the explicitly counted shifted odd-weight fold with exact integer
// arithmetic. Its running total is reused; no extra all-bucket pass is free.
let mut cases=0;let mut random=0xabc123u64;for size in 1..=64{for _ in 0..64{let v=(0..size).map(|_|{random^=random<<13;random^=random>>7;random^=random<<17;(random%1000)as i128-500}).collect::<Vec<_>>();let expect=v.iter().enumerate().map(|(i,&v)|(2*i+1)as i128*v).sum::<i128>();let mut adds=0;let result=if size==1{v[0]}else{let mut running=v[size-1];let mut weighted=running;for i in(1..size-1).rev(){running+=v[i];weighted+=running;adds+=2;}let total=running+v[0];adds+=1;adds+=1;2*weighted+total};assert_eq!(result,expect);assert_eq!(adds,2*(size-1));cases+=1;}}
let out=json!({"review_passed":true,"source_input_pins":pins.as_object().unwrap().len(),"successful_workflow_commands":2,"all_candidate_rows_and_correction_totals_rebuilt":true,"all176production_sources_hash_checked":true,"exact_original_phi_split_reused":true,"frozen_full_radix_model_reused_not_rescanned":true,"independent_odd_weight_fold_cases":cases,"independent_model_math_not_second_scalar_scan":true,"main_model_adds":main,"skew_correction_adds":skew,"complete_model_adds":complete,"frozen_full_radix_model_adds":634405,"native_selected":selected,"new_proofs":0,"proof_ledger":30708,"adopted":false,"goal_achieved":false});fs::write(format!("{R}/review.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Review PASS: {} pins, 2 commands, all rows/corrections, {cases} independent weighted-fold cases; native selected {selected}",pins.as_object().unwrap().len());}
